<?php
// Temporary owner-authorized auto review. Does not change audiences or publish drafts.
function cmAutoEnabled(): bool {return (socialContentLimits()['moderation_enabled']??true)===false;}
function cmAutoApprove(): array {
 static $running=false;if(!cmAutoEnabled()||$running||socialDb()->inTransaction())return [];
 $running=true;$result=['approved'=>0,'skipped'=>[]];$actor='system:testing-auto-review';
 $apply=function(string $kind,string $id,callable $work)use(&$result,$actor){try{socialDb()->beginTransaction();$work();crAudit($actor,$kind,$id,'approve','pending','approved','');socialDb()->commit();$result['approved']++;}catch(Throwable $e){if(socialDb()->inTransaction())socialDb()->rollBack();$result['skipped'][]=['kind'=>$kind,'id'=>$id,'reason'=>$e->getMessage()];}};
 try{
  scSchema();
  foreach(socialQuery("SELECT p.* FROM member_places p JOIN members m ON m.id=p.owner WHERE p.state IN ('pending','needs_info') AND m.state='active'")->fetchAll() as $r){$doc=json_decode($r['document'],true);if(!empty($doc['staged']))continue;
   $apply('place',$r['id'],function()use($r,$doc,$actor){networkApproveLocale('place',$r['id'],$doc['language']??'he',$doc,$actor);socialQuery("UPDATE member_places SET state='approved',moderator_note='' WHERE id=?",[$r['id']]);});
  }
  foreach(socialQuery("SELECT p.id FROM community_photo_review p JOIN members m ON m.id=p.owner WHERE p.state IN ('pending','needs_info') AND m.state='active'")->fetchAll() as $r)$apply('photo',$r['id'],fn()=>socialQuery("UPDATE community_photo_review SET state='approved' WHERE id=?",[$r['id']]));
  foreach(socialQuery("SELECT c.* FROM community_corrections c JOIN members m ON m.id=c.owner WHERE c.state IN ('pending','needs_info') AND m.state='active' ORDER BY c.created,c.id")->fetchAll() as $r)$apply('correction',$r['id'],function()use($r,$actor){
   $base=crPlaceBase($r['place'],$r['language']);if(crValue($base,$r['field'])!==json_decode($r['previous'],true))throw new DomainException('conflict');
   socialQuery('INSERT INTO community_place_fields VALUES(?,?,?,?,?) ON CONFLICT(place,language,field) DO UPDATE SET value=excluded.value,proposal=excluded.proposal',[$r['place'],$r['language'],$r['field'],$r['value'],$r['id']]);socialQuery("UPDATE community_corrections SET state='approved',reviewer=?,note='' WHERE id=?",[$actor,$r['id']]);
  });
  require_once ROOT.'/src/place-review.php';
  foreach(socialQuery("SELECT c.id FROM place_contributions c JOIN members m ON m.id=c.owner WHERE c.state='published' AND m.state='active' AND NOT EXISTS(SELECT 1 FROM member_places p WHERE 'community-'||p.id=c.place AND json_extract(p.document,'$.staged')=1 AND p.state='pending') AND COALESCE((SELECT action FROM community_decisions d WHERE d.kind='place_submission' AND d.target=c.id ORDER BY d.id DESC LIMIT 1),'') IN ('','needs_info') ORDER BY c.created,c.id")->fetchAll() as $r){try{$s=prSubmission($r['id']);prApply($r['id'],'approve',$s['version'],'',$actor);$result['approved']++;}catch(Throwable $e){$result['skipped'][]=['kind'=>'place_submission','id'=>$r['id'],'reason'=>$e->getMessage()];}}
  foreach(socialQuery("SELECT p.id,l.language,l.document FROM network_posts p JOIN members m ON m.id=p.owner JOIN network_localizations l ON l.kind='post' AND l.target=p.id WHERE p.state='pending' AND l.state='pending' AND m.state='active'")->fetchAll() as $r)$apply('post',$r['id'],function()use($r,$actor){networkApproveLocale('post',$r['id'],$r['language'],json_decode($r['document'],true),$actor);socialQuery("UPDATE network_posts SET state='published' WHERE id=?",[$r['id']]);});
  foreach(socialQuery("SELECT c.id FROM network_comments c JOIN members m ON m.id=c.owner WHERE c.state='pending' AND m.state='active'")->fetchAll() as $r)$apply('comment',$r['id'],fn()=>socialQuery("UPDATE network_comments SET state='published' WHERE id=?",[$r['id']]));
  foreach(socialQuery("SELECT t.* FROM member_trips t JOIN members m ON m.id=t.owner WHERE t.state='pending' AND t.pending_plan IS NOT NULL AND m.state='active'")->fetchAll() as $r)$apply('trip',$r['id'],function()use($r,$actor){$doc=json_decode($r['pending_plan'],true);foreach($doc['items'] as &$stop)if(networkItemForLanguage($stop['id'],$doc['language']??'he'))$stop['custom']=false;unset($stop);networkValidateRoute($doc);networkApproveLocale('trip',$r['id'],$doc['language']??'he',$doc,$actor);socialQuery("UPDATE member_trips SET public_plan=?,pending_plan=NULL,state='published',revision=revision+1 WHERE id=?",[json_encode($doc,JSON_UNESCAPED_UNICODE),$r['id']]);});
  foreach(socialQuery("SELECT s.* FROM network_submissions s JOIN members m ON m.id=s.owner WHERE s.state='pending' AND m.state='active' ORDER BY s.created")->fetchAll() as $r)$apply('translation',$r['id'],function()use($r,$actor){if((int)(networkLocale($r['kind'],$r['target'],$r['language'])['source_version']??0)!==(int)$r['base_version'])throw new DomainException('conflict');$target=networkOwnTarget(['id'=>$r['owner']],$r['kind'],$r['target']);if(in_array($target['state'],['blocked','rejected','removed'],true))throw new DomainException('blocked');$doc=json_decode($r['document'],true);if($r['kind']==='trip')networkValidateRoute($doc);networkApproveLocale($r['kind'],$r['target'],$r['language'],$doc,$actor);socialQuery("UPDATE network_submissions SET state='approved',note='' WHERE id=?",[$r['id']]);});
  journeyDb();foreach(socialQuery("SELECT r.id FROM journey_reviews r JOIN members m ON m.id=r.owner WHERE r.state='pending' AND m.state='active'")->fetchAll() as $r)$apply('journey_review',$r['id'],fn()=>socialQuery("UPDATE journey_reviews SET state='approved' WHERE id=?",[$r['id']]));
  scCatalogue(true);return $result;
 }finally{$running=false;}
}
